=== src/middlewares/published-only.ts
     1	import type { Core } from '@strapi/strapi';
     2	
     3	/**
     4	 * ADR-0002 / US-01-T-33: anonymous content API reads are always published-only.
     5	 *
     6	 * The REST API accepts `status=draft` from any caller allowed to `find`, so with a public `find`
     7	 * anyone could read drafts. This global middleware removes the publication parameters from every
     8	 * content API request that carries no credential. A request that does carry an `Authorization`
     9	 * header keeps them: an API token may read drafts (the editors' tooling), an invalid one is
    10	 * refused with 401 by Strapi's own authentication, and a users-permissions JWT has no content
    11	 * permissions (US-01-T-18).
    12	 *
    13	 * Re-verify on every Strapi upgrade: a new publication parameter would have to be added here
    14	 * (US-01-AC-28 checks it with the seeded draft field).
    15	 */
    16	const PUBLICATION_PARAMS = ['status', 'publicationFilter', 'hasPublishedVersion', 'publicationState'] as const;
    17	
    18	const publishedOnly: Core.MiddlewareFactory = () => {
    19	  return async (ctx, next) => {
    20	    if (ctx.path.startsWith('/api/') && !ctx.get('authorization')) {
    21	      const query = { ...(ctx.query as Record<string, unknown>) };
    22	      let changed = false;
    23	      for (const param of PUBLICATION_PARAMS) {
    24	        if (param in query) {
    25	          delete query[param];
    26	          changed = true;
    27	        }
    28	      }
    29	      if (changed) ctx.query = query as typeof ctx.query;
    30	    }
    31	    return next();
    32	  };
    33	};
    34	
    35	export default publishedOnly;
