    11	export async function ensureDevAdmin(strapi: Core.Strapi): Promise<void> {
    12	  const email = process.env['STRAPI_ADMIN_EMAIL'];
    13	  const password = process.env['STRAPI_ADMIN_PASSWORD'];
    14	  const users = strapi.service('admin::user');
    15	  if (await users.exists()) return;
    16	  if (!email || !password) {
    17	    strapi.log.warn('No admin user exists and STRAPI_ADMIN_EMAIL / STRAPI_ADMIN_PASSWORD are not set: create one at /admin.');
    18	    return;
    19	  }
    20	  await users.createFirstAdmin({ email, firstname: 'Admin', lastname: 'Desarrollo', password });
    21	  strapi.log.info('Created the development super admin from STRAPI_ADMIN_EMAIL.');
    22	}
