=== src/bootstrap/permissions.ts
     1	import type { Core } from '@strapi/strapi';
     2	
     3	/**
     4	 * ADR-0002 / US-01-T-18: the public role is reconciled to exactly the permissions below on every
     5	 * start. Nothing is configured by hand in the admin panel.
     6	 *
     7	 * US-02 adds `api::plan.plan.find` and US-03 `api::terms.terms.find`, each through its own spec.
     8	 */
     9	export const PUBLIC_PERMISSIONS = ['api::country.country.find', 'api::form-field.form-field.find'];
    10	
    11	const PERMISSION = 'plugin::users-permissions.permission';
    12	const ROLE = 'plugin::users-permissions.role';
    13	
    14	export async function reconcileRolePermissions(strapi: Core.Strapi): Promise<void> {
    15	  const publicRole = await strapi.db.query(ROLE).findOne({ where: { type: 'public' } });
    16	  if (!publicRole) throw new Error('The users-permissions public role does not exist');
    17	
    18	  const current = await strapi.db.query(PERMISSION).findMany({ where: { role: publicRole.id } });
    19	  const wanted = new Set(PUBLIC_PERMISSIONS);
    20	
    21	  for (const permission of current) {
    22	    if (!wanted.has(permission.action)) await strapi.db.query(PERMISSION).delete({ where: { id: permission.id } });
    23	  }
    24	  const present = new Set(current.map((permission) => permission.action));
    25	  for (const action of PUBLIC_PERMISSIONS) {
    26	    if (!present.has(action)) await strapi.db.query(PERMISSION).create({ data: { action, role: publicRole.id } });
    27	  }
    28	
    29	  // The authenticated role gets no content permission (the app has no end-user accounts).
    30	  const authenticatedRole = await strapi.db.query(ROLE).findOne({ where: { type: 'authenticated' } });
    31	  if (authenticatedRole) {
    32	    await strapi.db.query(PERMISSION).deleteMany({
    33	      where: { role: authenticatedRole.id, action: { $startsWith: 'api::' } },
    34	    });
    35	  }
    36	
    37	  // Self-registration is closed (the plugin creates it open on a fresh database).
    38	  const store = strapi.store({ type: 'plugin', name: 'users-permissions' });
    39	  const advanced = ((await store.get({ key: 'advanced' })) ?? {}) as Record<string, unknown>;
    40	  if (advanced['allow_register'] !== false) await store.set({ key: 'advanced', value: { ...advanced, allow_register: false } });
    41	}
