     1	import { factories } from '@strapi/strapi';
     2	
     3	/**
     4	 * `locale` is a reserved Strapi attribute name (the Document Service system field), so the BCP 47
     5	 * tag of a country is stored in `localeTag`. The contract of ADR-0001 and spec 7.3 (and every
     6	 * consumer) calls it `locale`, so the content API keeps answering `locale`: a `fields[]=locale`
     7	 * selection is mapped to `localeTag`, and the attribute is renamed in the response.
     8	 */
     9	const API_NAME = 'locale';
    10	const STORED_NAME = 'localeTag';
    11	
    12	type CountryItem = Record<string, unknown>;
    13	
    14	function renameInFields(fields: unknown): unknown {
    15	  if (typeof fields === 'string') return fields === API_NAME ? STORED_NAME : fields;
    16	  if (Array.isArray(fields)) return fields.map((name) => (name === API_NAME ? STORED_NAME : name));
    17	  return fields;
    18	}
    19	
    20	function toApiShape(item: CountryItem): CountryItem {
    21	  if (!(STORED_NAME in item)) return item;
    22	  const { [STORED_NAME]: tag, ...rest } = item;
    23	  return { ...rest, [API_NAME]: tag };
    24	}
    25	
    26	export default factories.createCoreController('api::country.country', ({ strapi }) => ({
    27	  async find(ctx) {
    28	    const query = ctx.query as Record<string, unknown>;
    29	    if ('fields' in query) ctx.query = { ...query, fields: renameInFields(query['fields']) } as typeof ctx.query;
    30	    const result = (await super.find(ctx)) as { data: CountryItem[]; meta: unknown };
    31	    return { ...result, data: result.data.map(toApiShape) };
    32	  },
    33	}));
