=== src/documents/unique-field-key.ts
     1	import type { Core } from '@strapi/strapi';
     2	import { errors } from '@strapi/utils';
     3	
     4	/**
     5	 * ADR-0001 / US-01-T-34: a `form-field` `key` is unique per country.
     6	 *
     7	 * Strapi's `unique` is global (or per locale), never scoped by a relation, so it is enforced here,
     8	 * as a Document Service middleware on create, update and publish. Drafts are compared because
     9	 * every document always has a draft row, so the draft is the current state of the content.
    10	 */
    11	
    12	const FORM_FIELD = 'api::form-field.form-field';
    13	const GUARDED_ACTIONS = new Set(['create', 'update', 'publish']);
    14	
    15	type Relation = unknown;
    16	
    17	/** The documentId a relation value points to, whatever shape the caller used (string, { documentId }, connect, set). */
    18	function relatedDocumentId(value: Relation): string | undefined {
    19	  if (typeof value === 'string') return value;
    20	  if (Array.isArray(value)) return relatedDocumentId(value[0]);
    21	  if (value && typeof value === 'object') {
    22	    const shape = value as Record<string, unknown>;
    23	    if (typeof shape['documentId'] === 'string') return shape['documentId'];
    24	    if ('set' in shape) return relatedDocumentId(shape['set']);
    25	    if ('connect' in shape) return relatedDocumentId(shape['connect']);
    26	  }
    27	  return undefined;
    28	}
    29	
    30	export function registerUniqueFieldKey(strapi: Core.Strapi): void {
    31	  strapi.documents.use(async (context, next) => {
    32	    if (context.uid !== FORM_FIELD || !GUARDED_ACTIONS.has(context.action)) return next();
    33	
    34	    const params = (context.params ?? {}) as { documentId?: string; data?: Record<string, unknown> };
    35	    const documents = strapi.documents(FORM_FIELD);
    36	    const data = params.data ?? {};
    37	    let key = typeof data['key'] === 'string' ? data['key'] : undefined;
    38	    let countryId = 'country' in data ? relatedDocumentId(data['country']) : undefined;
    39	
    40	    // Whatever the call does not change comes from the stored draft (update, publish).
    41	    if (params.documentId && (key === undefined || (!('country' in data) && countryId === undefined))) {
    42	      const current = await documents.findOne({
    43	        documentId: params.documentId,
    44	        status: 'draft',
    45	        fields: ['key'],
    46	        populate: { country: { fields: ['documentId'] } },
    47	      });
    48	      if (current) {
    49	        key ??= current['key'] as string;
    50	        if (!('country' in data)) countryId = (current['country'] as { documentId?: string } | null)?.documentId;
    51	      }
    52	    }
    53	
    54	    // Without a key or a country there is nothing to compare; a missing country is rejected on publish (strictRelations).
    55	    if (key && countryId) {
    56	      const clash = await documents.findFirst({
    57	        status: 'draft',
    58	        fields: ['documentId'],
    59	        filters: {
    60	          key: { $eq: key },
    61	          country: { documentId: { $eq: countryId } },
    62	          ...(params.documentId ? { documentId: { $ne: params.documentId } } : {}),
    63	        },
    64	      });
    65	      if (clash) {
    66	        throw new errors.ApplicationError(`Ya existe un campo con la clave "${key}" en este país.`);
    67	      }
    68	    }
    69	    return next();
    70	  });
    71	}

