     5	  currencyCode: string;
     6	  /** BCP 47 tag. Stored as `localeTag`: `locale` is a reserved Strapi attribute, the API still answers `locale`. */
     7	  localeTag: string;
     8	  sortOrder: number;
     9	}
    10	
    11	export const SEED_COUNTRIES: SeedCountry[] = [
    12	  { code: 'CO', name: 'Colombia', currencyCode: 'COP', localeTag: 'es-CO', sortOrder: 10 },
    13	  { code: 'CL', name: 'Chile', currencyCode: 'CLP', localeTag: 'es-CL', sortOrder: 20 },
    14	];
