     6	const FORM_FIELD = 'api::form-field.form-field';
     7	
     8	function fieldData(field: FieldSeed, countryDocumentId: string): Record<string, unknown> {
     9	  const { draftOnly: _draftOnly, options, rules, ...attributes } = field;
    10	  return {
    11	    ...attributes,
    12	    options: (options ?? []).map(([value, label], index) => ({ value, label, sortOrder: (index + 1) * 10 })),
    13	    rules: (rules ?? []).map((rule) => ({ ...rule })),
    14	    country: { connect: [countryDocumentId] },
    15	  };
    16	}
    17	
    18	/**
    19	 * Idempotent seed (US-01-T-17): each item is looked up by its natural key and created only when
    20	 * missing, so a restart never duplicates or overwrites what editors changed. Published, except the
    21	 * draft-only field (US-01-AC-13). Fields are looked up by their draft, which every document has,
    22	 * so an unpublished seed field is not created a second time.
    23	 */
    24	export async function seed(strapi: Core.Strapi): Promise<void> {
    25	  const countries = strapi.documents(COUNTRY);
    26	  const fields = strapi.documents(FORM_FIELD);
    27	
    28	  for (const country of SEED_COUNTRIES) {
    29	    let existing = await countries.findFirst({ filters: { code: country.code }, status: 'draft' });
    30	    if (!existing) existing = await countries.create({ data: country, status: 'published' });
    31	
    32	    for (const field of SEED_FORM_FIELDS[country.code] ?? []) {
    33	      const found = await fields.findFirst({
    34	        filters: { key: field.key, country: { documentId: existing.documentId } },
    35	        status: 'draft',
    36	      });
    37	      if (!found) {
    38	        await fields.create({ data: fieldData(field, existing.documentId) as never, status: field.draftOnly ? 'draft' : 'published' });
