const { chromium } = require('/Users/cristiansabogal/Proyectos/multicountry-car-insurance/frontend/node_modules/playwright');
(async () => {
  const browser = await chromium.launch();
  for (const [w, h] of [[320, 640], [360, 740], [1280, 800]]) {
    const page = await browser.newPage({ viewport: { width: w, height: h } });
    await page.goto('http://localhost:8080/co/datos');
    await page.getByRole('button', { name: 'Continuar' }).waitFor();
    const r = await page.evaluate(() => {
      const de = document.documentElement;
      const small = [...document.querySelectorAll('input,select,button,a')].map((e) => { const b = e.getBoundingClientRect(); return { id: e.id || e.textContent.trim(), w: Math.round(b.width), h: Math.round(b.height) }; }).filter((x) => x.w < 24 || x.h < 24);
      return { scrollW: de.scrollWidth, clientW: de.clientWidth, small, focused: document.activeElement?.tagName + ':' + document.activeElement?.textContent?.slice(0, 40) };
    });
    console.log(w, JSON.stringify(r));
    await page.close();
  }
  // chooser & unknown-country headings / landmarks
  const page = await browser.newPage();
  await page.goto('http://localhost:8080/');
  await page.getByRole('link', { name: 'Chile' }).waitFor();
  console.log('chooser:', await page.locator('main').ariaSnapshot());
  await page.goto('http://localhost:8080/ar/datos');
  await page.getByRole('link', { name: 'Chile' }).waitFor();
  console.log('unknown:', await page.locator('main').ariaSnapshot(), 'title:', await page.title());
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
